#!/usr/bin/env node
// One-shot dev script: captures the first [surah, ayah] of every one of the 604
// mushaf pages from the Quran.com Foundation API v4 and writes the checked-in
// src/lib/page-starts.ts (the offline PAGE_STARTS table). Mirrors
// fetch-surah-names.mjs: fetch, validate shape and structure, throw on any
// mismatch, write a checked-in generated file.
//
// Run manually (this environment blocks plain node fetch; --use-system-ca fixes
// it, same as the mushaf SSG build):
//   NODE_OPTIONS=--use-system-ca node scripts/fetch-page-starts.mjs
//
// This script is NOT part of the build. PAGE_STARTS is verified structural
// pagination captured once and committed; navigation.test.ts guards it against
// drift. Never hand-author the 604 verseKeys — that violates the binding
// content-verification rule (they are verified references from the API).

import { readFile, writeFile } from "node:fs/promises";
import { join, dirname } from "node:path";
import { fileURLToPath } from "node:url";

const __dirname = dirname(fileURLToPath(import.meta.url));
const REPO_ROOT = join(__dirname, "..");
const INDEX_PATH = join(REPO_ROOT, "src", "data", "content", "surah-index.json");
const OUT_PATH = join(REPO_ROOT, "src", "lib", "page-starts.ts");
const API_BASE = "https://api.quran.com/api/v4/verses/by_page";

const TOTAL_PAGES = 604;
const TOTAL_VERSES = 6236;

// Fetch one page's first verse_key with a small retry, mirroring quran-api's
// fetchWithRetry policy (4xx fails fast; 5xx / network errors retry).
async function fetchPageStart(page, retries = 3) {
  const url = `${API_BASE}/${page}?per_page=1&fields=verse_key`;
  for (let attempt = 0; attempt <= retries; attempt++) {
    try {
      const res = await fetch(url, { headers: { Accept: "application/json" } });
      if (res.status >= 400 && res.status < 500) {
        throw new Error(`page ${page}: ${res.status} ${res.statusText} (no retry)`);
      }
      if (!res.ok) throw new Error(`page ${page}: ${res.status} ${res.statusText}`);
      const json = await res.json();
      const key = json?.verses?.[0]?.verse_key;
      if (typeof key !== "string" || !/^\d{1,3}:\d{1,3}$/.test(key)) {
        throw new Error(`page ${page}: unexpected /verses/by_page shape (missing verses[0].verse_key)`);
      }
      const [surah, ayah] = key.split(":").map(Number);
      return [surah, ayah];
    } catch (err) {
      if (attempt === retries || /no retry/.test(String(err))) throw err;
      await new Promise((r) => setTimeout(r, 400 * 2 ** attempt));
    }
  }
  throw new Error(`page ${page}: exhausted retries`);
}

// Fail-fast structural validation, mirroring the chapters.length !== 114 guard
// in fetch-surah-names.mjs. Refuses to write on any mismatch.
function validate(pageStarts, ayahCount) {
  if (pageStarts.length !== TOTAL_PAGES) {
    throw new Error(`expected ${TOTAL_PAGES} page starts, captured ${pageStarts.length}`);
  }
  const [firstS, firstA] = pageStarts[0];
  if (firstS !== 1 || firstA !== 1) {
    throw new Error(`page 1 must start at 1:1, captured ${firstS}:${firstA}`);
  }
  // Strictly monotonic by (surah, ayah): each page starts at a new, later verse.
  for (let i = 1; i < pageStarts.length; i++) {
    const [s, a] = pageStarts[i];
    const [ps, pa] = pageStarts[i - 1];
    if (!(s > ps || (s === ps && a > pa))) {
      throw new Error(`page ${i + 1} start ${s}:${a} is not after page ${i} start ${ps}:${pa}`);
    }
  }
  // Every start ayah is within its surah's real ayah count.
  for (let i = 0; i < pageStarts.length; i++) {
    const [s, a] = pageStarts[i];
    const count = ayahCount.get(s);
    if (!count || a < 1 || a > count) {
      throw new Error(`page ${i + 1} start ${s}:${a} is out of surah ${s}'s range (1..${count ?? 0})`);
    }
  }
  // Page-by-page walk: from each page's start to the next page's start
  // (exclusive), honoring each surah's real ayah count for rollover, must
  // enumerate exactly 6236 verses ending at 114:6 (same guard shape as the
  // JUZ_STARTS enumeration).
  let total = 0;
  let lastKey = null;
  for (let p = 1; p <= TOTAL_PAGES; p++) {
    const [startS, startA] = pageStarts[p - 1];
    const [endS, endA] = p < TOTAL_PAGES ? pageStarts[p] : [115, 1]; // sentinel past 114:6
    let s = startS;
    let a = startA;
    while (s < endS || (s === endS && a < endA)) {
      total++;
      lastKey = `${s}:${a}`;
      a++;
      if (a > ayahCount.get(s)) {
        s++;
        a = 1;
      }
    }
  }
  if (total !== TOTAL_VERSES) {
    throw new Error(`page walk enumerated ${total} verses, expected ${TOTAL_VERSES}`);
  }
  if (lastKey !== "114:6") {
    throw new Error(`page walk ended at ${lastKey}, expected 114:6`);
  }
}

function render(pageStarts) {
  const header = `// GENERATED by scripts/fetch-page-starts.mjs — DO NOT EDIT by hand.
// The first [surah, ayah] of each of the 604 pages of the standard Hafs 'an
// 'Asim 604-page Madinah mushaf. Verified structural pagination (the same in
// every printing of that mushaf), captured once from
// api.quran.com/api/v4/verses/by_page/{1..604} and cross-checked by enumeration
// to total exactly 6236 verses with no gaps or duplicates (page 604 runs to
// 114:6). These are verseKey REFERENCES, not generated content — the same
// justification JUZ_STARTS carries. Re-run the generator after the mushaf
// pagination reference changes; navigation.test.ts is the drift guard.
// PAGE_STARTS[p - 1] = first verse of page p.
`;
  const lines = pageStarts
    .map(([s, a], i) => `  [${s}, ${a}], // page ${i + 1}`)
    .join("\n");
  return `${header}export const PAGE_STARTS: ReadonlyArray<readonly [number, number]> = [\n${lines}\n];\n`;
}

async function main() {
  const raw = await readFile(INDEX_PATH, "utf8");
  const index = JSON.parse(raw);
  if (!Array.isArray(index) || index.length !== 114) {
    throw new Error(`surah-index.json must hold 114 surahs, found ${Array.isArray(index) ? index.length : "non-array"}`);
  }
  const ayahCount = new Map(index.map((s) => [s.number, s.versesCount]));

  console.log(`Fetching first verse_key of pages 1..${TOTAL_PAGES} from Quran.com API v4...`);
  const pageStarts = [];
  for (let p = 1; p <= TOTAL_PAGES; p++) {
    pageStarts.push(await fetchPageStart(p));
    if (p % 50 === 0 || p === TOTAL_PAGES) console.log(`  ...captured ${p}/${TOTAL_PAGES}`);
  }

  console.log("Validating captured table (604 / monotonic / in-range / 6236-walk ending 114:6)...");
  validate(pageStarts, ayahCount);

  await writeFile(OUT_PATH, render(pageStarts), "utf8");
  console.log(`Wrote ${OUT_PATH} (${pageStarts.length} page starts).`);
}

main().catch((err) => {
  console.error(err);
  process.exit(1);
});
